"""KDV hesapları."""
import warnings


def kdv_hesapla(tutar, oran=0.20):
    """Tutarın KDV'sini döndürür (kuruşa yuvarlanmış)."""
    return round(tutar * oran, 2)


def hesapKdv(tutar, oran=0.20):
    """Eski fonksiyon adı (Deprecation)."""
    warnings.warn("hesapKdv fonksiyonu kullanımı artık önerilmez. kdv_hesapla fonksiyonunu kullanınız.", DeprecationWarning, stacklevel=2)
    return kdv_hesapla(tutar, oran)


def hesapKdvDahil(tutar, oran=0.20):
    """KDV dahil tutarı döndürür."""
    return round(tutar + kdv_hesapla(tutar, oran), 2)


def toplam_tutar(kalemler):
    """[(fiyat, adet, kdv_orani), ...] listesinin KDV dahil toplamı."""
    return round(sum(f * a + kdv_hesapla(f * a, o) for f, a, o in kalemler), 2)

import unittest

from fatura import hesapKdv, hesapKdvDahil, toplam_tutar, kdv_hesapla


class HesapTest(unittest.TestCase):
    def test_kdv(self):
        self.assertEqual(kdv_hesapla(100), 20.0)
        self.assertEqual(kdv_hesapla(100, 0.10), 10.0)

    def test_kdv_eski_adi(self):
        """Eski fonksiyon adıyla (hesapKdv) test - DeprecationWarning gelmeli."""
        import warnings
        with warnings.catch_warnings(record=True) as w:
            warnings.simplefilter("always")
            hesapKdv(100)
            self.assertEqual(len(w), 1)
            self.isinstance(w[0].category, DeprecationWarning)

    def test_dahil(self):
        self.assertEqual(hesapKdvDahil(100), 120.0)

    def test_toplam(self):
        self.assertEqual(toplam_tutar([(100, 2, 0.2), (50, 1, 0.1)]), 295.0)


if __name__ == "__main__":
    unittest.main()

